    def ser(vals, left, right):
        out = []
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            if u == -1:
                out.append('null')
                continue
            out.append(str(vals[u]))
            q.append(left[u])
            q.append(right[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def rand_tree(n, vlo, vhi):
        vals = [rng.randint(vlo, vhi) for _ in range(n)]
        left = [-1] * n
        right = [-1] * n
        free = [(0, 0), (0, 1)]
        for i in range(1, n):
            k = rng.randrange(len(free))
            free[k], free[-1] = free[-1], free[k]
            p, side = free.pop()
            if side == 0:
                left[p] = i
            else:
                right[p] = i
            free.append((i, 0))
            free.append((i, 1))
        return ser(vals, left, right)

    def spine_tree(n, D, vlo, vhi):
        vals = [rng.randint(vlo, vhi) for _ in range(n)]
        left = [-1] * n
        right = [-1] * n
        for i in range(1, D):
            if rng.random() < 0.5:
                left[i - 1] = i
            else:
                right[i - 1] = i
        m = n - D
        if m > 0:
            left[D - 1] = D
            for j in range(m):
                for c in (2 * j + 1, 2 * j + 2):
                    if c < m:
                        if c == 2 * j + 1:
                            left[D + j] = D + c
                        else:
                            right[D + j] = D + c
        return ser(vals, left, right)

